import torch
from torch.utils.cpp_extension import load_inline

# CUDA kernel implementation
cuda_source = """
#include <cuda_fp16.h>
#include <cuda_runtime.h>

__global__ void avg_pool_1d_kernel(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * in_channels * output_length;

    if (idx >= total_elements) return;

    int batch_idx = idx / (in_channels * output_length);
    int channel_idx = (idx % (in_channels * output_length)) / output_length;
    int out_pos = idx % output_length;

    // Calculate input start position
    int input_start = out_pos * stride - padding;

    // Initialize accumulator with zero
    float sum = 0.0f;
    int count = 0;

    // Perform average pooling
    for (int k = 0; k < kernel_size; ++k) {
        int input_pos = input_start + k;

        // Check bounds
        if (input_pos >= 0 && input_pos < input_length) {
            int input_idx = batch_idx * (in_channels * input_length) +
                           channel_idx * input_length +
                           input_pos;
            sum += __half2float(input[input_idx]);
            count++;
        }
    }

    // Compute average and store result
    if (count > 0) {
        float avg = sum / count;
        int output_idx = batch_idx * (in_channels * output_length) +
                        channel_idx * output_length +
                        out_pos;
        output[output_idx] = __float2half(avg);
    } else {
        int output_idx = batch_idx * (in_channels * output_length) +
                        channel_idx * output_length +
                        out_pos;
        output[output_idx] = __float2half(0.0f);
    }
}

// Host wrapper function
extern "C" void launch_avg_pool_1d(
    const half* input,
    half* output,
    int batch_size,
    int in_channels,
    int input_length,
    int output_length,
    int kernel_size,
    int stride,
    int padding
) {
    int total_elements = batch_size * in_channels * output_length;
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    avg_pool_1d_kernel<<<grid_size, block_size>>>(
        input, output, batch_size, in_channels, input_length,
        output_length, kernel_size, stride, padding
    );

    cudaDeviceSynchronize();
}
"""

# Compile and load the CUDA extension
avg_pool_ext = load_inline(
    name="avg_pool_1d",
    cpp_sources=[],
    cuda_sources=[cuda_source],
    functions=["launch_avg_pool_1d"],
    verbose=False
)

class ModelNew(torch.nn.Module):
    def __init__(self, kernel_size: int, stride: int = 1, padding: int = 0):
        super(ModelNew, self).__init__()
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Calculate output length
        input_length = x.size(-1)
        output_length = (input_length + 2 * self.padding - self.kernel_size) // self.stride + 1

        # Prepare output tensor
        output = torch.empty(
            x.size(0), x.size(1), output_length,
            dtype=torch.float16, device=x.device
        )

        # Launch CUDA kernel
        avg_pool_ext.launch_avg_pool_1d(
            x.contiguous().data_ptr(),
            output.data_ptr(),
            x.size(0),
            x.size(1),
            input_length,
            output_length,
            self.kernel_size,
            self.stride,
            self.padding
        )

        return output

# Test parameters
batch_size = 64
in_channels = 128
input_length = 65536
kernel_size = 8
stride = 1
padding = 4

def get_inputs():
    x = torch.rand(batch_size, in_channels, input_length, dtype=torch.float16)
    return [x]

def get_init_inputs():
    return [kernel_size, stride, padding]
